// Marquee infinito. O original (spell.sh) injeta os keyframes com <style jsx>
// e é client component; aqui as regras vivem em globals.css e isto é um server
// component — a faixa é decorativa e não precisa de JS nenhum.
//
// Duas trilhas idênticas deslizam -100%: quando a primeira sai da tela, a
// segunda já ocupou o lugar. A segunda é aria-hidden para o leitor de tela não
// ouvir a lista duas vezes.

import { Fragment } from "react";
import type { CSSProperties, ReactNode } from "react";
import { cn } from "@/lib/utils";

export function Marquee({
  children,
  className,
  duration = 32,
  gap = 40,
  direction = "left",
  pauseOnHover = true,
  /** Quantas vezes o conteúdo se repete dentro de cada trilha. Com lista curta,
   *  uma cópia só não cobre a largura da tela e abre um vão na volta do ciclo —
   *  suba para 2 ou 3 quando a faixa tiver poucos itens. */
  repeat = 1,
}: {
  children: ReactNode;
  className?: string;
  duration?: number;
  gap?: number;
  direction?: "left" | "right";
  pauseOnHover?: boolean;
  repeat?: number;
}) {
  const track = Array.from({ length: Math.max(1, repeat) }, (_, i) => (
    <Fragment key={i}>{children}</Fragment>
  ));

  return (
    <div
      className={cn("marquee", className)}
      data-direction={direction}
      data-pause={pauseOnHover}
      style={
        {
          "--marquee-duration": `${duration}s`,
          "--marquee-gap": `${gap}px`,
        } as CSSProperties
      }
    >
      <div className="marquee-track">{track}</div>
      <div aria-hidden className="marquee-track">
        {track}
      </div>
    </div>
  );
}

/* ============ Marquee ============ */
/* Duas trilhas idênticas deslizando -100%: quando a primeira sai, a segunda
   já está no lugar. Animação de transform, roda no compositor. */
.marquee {
  display: flex;
  width: 100%;
  overflow: hidden;
  gap: var(--marquee-gap, 0px);
  mask-image: linear-gradient(to right, transparent, #000 8%, #000 92%, transparent);
  -webkit-mask-image: linear-gradient(to right, transparent, #000 8%, #000 92%, transparent);
}

.marquee-track {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: var(--marquee-gap, 0px);
  padding-inline-end: var(--marquee-gap, 0px);
  min-width: 100%;
  animation: marquee-x var(--marquee-duration, 32s) linear infinite;
}

.marquee[data-direction="right"] .marquee-track {
  animation-direction: reverse;
}

.marquee[data-pause="true"]:hover .marquee-track {
  animation-play-state: paused;
}

@keyframes marquee-x {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-100%);
  }
}

/* Sem movimento, a faixa vira lista estática — nunca barra de rolagem: obrigar
   a arrastar para ler a lista é pior do que a animação que se quis evitar. */
@media (prefers-reduced-motion: reduce) {
  .marquee {
    display: block;
    overflow: visible;
    mask-image: none;
    -webkit-mask-image: none;
  }

  .marquee-track {
    flex-wrap: wrap;
    justify-content: center;
    min-width: 0;
    padding-inline-end: 0;
    animation: none;
  }

  /* a segunda trilha é só a cópia do efeito */
  .marquee-track + .marquee-track {
    display: none;
  }
}
